INSERT INTO _teaser_card_plan (site_id, column_name, old_value, new_value, change_key, reason, premise, evidence) VALUES
    ('0025b0ba-fd74-4c08-96e3-acc17956aa44'::uuid, 'card_description', 'Excavated ground at the foot of Mount Meron exceeded six acres. Khirbet Shema holds a large Jewish village of the Roman and Byzantine periods, with its synagogue and mausoleum.', NULL, 'teaser-card-s039:0025b0ba-fd74-4c08-96e3-acc17956aa44:card_description', 'teaser-card-s039 (card-clear-recheck-adversarial-failed): card cleared (recheck-adversarial-failed)', '||d656109b8605c184ef1a99a800d9c94f6f9ddb2af2dae53e68ec97018ad4422e', '[{"source": "lane WB run wb-recheck-2026-10-24: recheck-adversarial-failed", "url": "output/remediation/teaser/runs/wb-recheck-2026-10-24/OUTCOMES.jsonl", "quote": "No sentence of the description supports the claim: the excavated ground at the site exceeded six acres; The card says the excavated ground exceeded six acres, but S4 says only that ''the area recovered'' exceeded six acres, and the source behind that sentence (Modern Data, January 1974, ''The Synagogue of Khirbet Shema Restored'', https://bitsavers.org/magazines/Modern_Data/Modern_Data_1974_01.pdf) shows the six acres are the extent of the village whose plan was recorded, not ground that was dug: ''By the end of the first summer''s work they had recovered the plan of most of the village, an area of more than six acres''; drop the six-acre claim or reword it as the village''s extent (a village of more than six acres) instead of excavated ground."}]'::jsonb),
    ('0047ae41-af8e-44e1-b196-4035f5860554'::uuid, 'card_description', 'Gonnus stood on the north side of the Peneius, near the entrance of the only two passes by which an enemy could enter Thessaly from the north. Xerxes I''s army came that way.', NULL, 'teaser-card-s039:0047ae41-af8e-44e1-b196-4035f5860554:card_description', 'teaser-card-s039 (card-clear-recheck-contradicted): card cleared (recheck-contradicted)', '||0402574baef52c15ad7def4e353a42a6afa2f70c5c297809acf3e5a2e71cc05b', '[{"source": "lane WB run wb-recheck-2026-10-24: recheck-contradicted", "url": "output/remediation/teaser/runs/wb-recheck-2026-10-24/OUTCOMES.jsonl", "quote": "The web check contradicts: These were the only two passes by which an enemy could enter Thessaly from the north (https://www.cristoraul.org/ENGLISH/readinghall/THIRDMILLENNIUMLIBRARY/PERSIAN-EMPIRE/CHAPTER-9-XERXES-INVASION-OF-GREECE.html: \"Tempe is not the only gate into Thessaly from the north. Apart from the mountain path by Gonnus, which is not of much account, there are in chief the passes of Petra and Volustana.\")"}]'::jsonb),
    ('006294ae-548b-40ac-9271-03a017df7217'::uuid, 'card_description', 'A causeway links El Tintal to El Mirador, the larger site. About 25 km northeast of Carmelita, El Tintal is the second-largest in the Mirador Basin, among the four largest in northern Petén.', NULL, 'teaser-card-s039:006294ae-548b-40ac-9271-03a017df7217:card_description', 'teaser-card-s039 (card-clear-recheck-check-failed): card cleared (recheck-check-failed)', '||0a8179eae6c1295bc913120593d46565bd6a2efff84f7d313ffc3f26cf5747a4', '[{"source": "lane WB run wb-recheck-2026-10-24: recheck-check-failed", "url": "output/remediation/teaser/runs/wb-recheck-2026-10-24/OUTCOMES.jsonl", "quote": "No sentence of the description supports the claim: a causeway links El Tintal to El Mirador today (present tense); S3 says El Tintal ''was linked'' to El Mirador by a causeway (past tense); the card''s ''A causeway links El Tintal to El Mirador'' gives that past state as a present one - write ''A causeway once linked El Tintal to El Mirador'' or ''El Tintal was linked to El Mirador by a causeway''."}]'::jsonb),
    ('00cb2c16-2b30-42ce-aeb0-b258761ea754'::uuid, 'card_description', 'Where the Exe and Lowman meet, Stone Age flint tools mark Tiverton, the town on two fords. Cranmore Castle, over 15 acres, possibly a livestock enclosure, market site or tribal oppidum.', NULL, 'teaser-card-s039:00cb2c16-2b30-42ce-aeb0-b258761ea754:card_description', 'teaser-card-s039 (card-clear-recheck-adversarial-failed): card cleared (recheck-adversarial-failed)', '||3d9ff47e5fc947907e5c18ea3f1b89e4f142b30fefa820d4d23c9780e85e4d59', '[{"source": "lane WB run wb-recheck-2026-10-24: recheck-adversarial-failed", "url": "output/remediation/teaser/runs/wb-recheck-2026-10-24/OUTCOMES.jsonl", "quote": "The tone rules are broken (see the checker''s reasons).; The second sentence (''Cranmore Castle, over 15 acres, possibly a livestock enclosure, market site or tribal oppidum.'') has no verb, so the card is not two English sentences and never says that Cranmore Castle is an enclosure at Tiverton; rewrite it as a full sentence that ties the enclosure to the town, for example ''Above the town, Cranmore Castle encloses over 15 acres; its function is debated: possibly a livestock enclosure, market site or tribal oppidum.''"}]'::jsonb),
    ('01914c11-fb33-4778-a0ef-fd616ff33b88'::uuid, 'card_description', 'Cumae, the first Greek colony on mainland Italy, was founded around 725 BC from Chalcis. Famed as the home of the Cumaean Sibyl, it holds a purported 130-metre underground corridor.', NULL, 'teaser-card-s039:01914c11-fb33-4778-a0ef-fd616ff33b88:card_description', 'teaser-card-s039 (card-clear-recheck-disputed): card cleared (recheck-disputed)', '||ac17d4d73741d5cc0b56ed03708e78afdde1c26ef917b7441070550c0aec5200', '[{"source": "lane WB run wb-recheck-2026-10-24: recheck-disputed", "url": "output/remediation/teaser/runs/wb-recheck-2026-10-24/OUTCOMES.jsonl", "quote": "The web check finds the claim disputed (reputable sources disagree): Cumae was founded around 725 BC (https://www.encyclopedia.com/reference/encyclopedias-almanacs-transcripts-and-maps/cumae: \"it seems to have been founded c.750 BC by Chalcis\") - hedge it or drop it"}]'::jsonb),
    ('01b50bc7-3e36-494e-9a91-fc4d60323ada'::uuid, 'card_description', 'Franchthi Cave overlooks Kiladha Bay, where finds trace the transition from Paleolithic hunter-gatherers to Neolithic farmers, with domesticated plants and animals appearing around 7,000 BC.', NULL, 'teaser-card-s039:01b50bc7-3e36-494e-9a91-fc4d60323ada:card_description', 'teaser-card-s039 (card-clear-recheck-disputed): card cleared (recheck-disputed)', '||1db243cc9f98c16a26c765b1c5c6e6f7897eeefcec6aec189128482e8fe5f7fc', '[{"source": "lane WB run wb-recheck-2026-10-24: recheck-disputed", "url": "output/remediation/teaser/runs/wb-recheck-2026-10-24/OUTCOMES.jsonl", "quote": "The web check could not prove: Finds at the cave trace a sequence from the Paleolithic to the Neolithic; The web check finds the claim disputed (reputable sources disagree): Domesticated plants and animals appear around 7,000 BC (https://www.argolisculture.gr/en/list-of-monuments/franchthi-cave/: \"There was a transition to the new agricultural food production of the Neolithic period, with the appearance of domesticated animals and plants in the cave, a little after 6000 BC\") - hedge it or drop it"}]'::jsonb),
    ('01f3d961-e2cf-4a3d-bc36-7e9976efe93e'::uuid, 'card_description', '54 km southeast of Puno in the Titicaca Basin, Jisk''a Iru Muqu was occupied from circa 3400-1600 BCE. Excavations recovered obsidian tools, a gold necklace and early domestic architecture.', NULL, 'teaser-card-s039:01f3d961-e2cf-4a3d-bc36-7e9976efe93e:card_description', 'teaser-card-s039 (card-clear-recheck-unproven): card cleared (recheck-unproven)', '||c27be8decdb3a8a45986cb35874101cd73e8c58d8a3a10558ffcd04dcf9e613a', '[{"source": "lane WB run wb-recheck-2026-10-24: recheck-unproven", "url": "output/remediation/teaser/runs/wb-recheck-2026-10-24/OUTCOMES.jsonl", "quote": "The web check could not prove: Jisk''a Iru Muqu is an archaeological (Archaic-Formative settlement) site in the Lake Titicaca Basin of Peru; The web check could not prove: Excavations recovered a gold necklace; The web check could not prove: Excavations recovered early domestic architecture"}]'::jsonb),
    ('03a7a357-12a8-40f9-ae6a-9cef78135fd3'::uuid, 'card_description', 'Dubris, on the site of Dover, became the main Roman cross-Channel port, taking over from Rutupiae. A 1970s bypass uncovered its remains; an eight-week excavation found a Roman mansio.', NULL, 'teaser-card-s039:03a7a357-12a8-40f9-ae6a-9cef78135fd3:card_description', 'teaser-card-s039 (card-clear-recheck-disputed): card cleared (recheck-disputed)', '||d2dc8b1e569dd57f4d582b0f8e881c5089ffa1b240bd2f65794dbb5d718037c1', '[{"source": "lane WB run wb-recheck-2026-10-24: recheck-disputed", "url": "output/remediation/teaser/runs/wb-recheck-2026-10-24/OUTCOMES.jsonl", "quote": "The web check finds the claim disputed (reputable sources disagree): Dubris became the main Roman cross-Channel port, taking over from Rutupiae (Richborough) (https://www.english-heritage.org.uk/visit/places/richborough-roman-fort-and-amphitheatre/history-and-stories/history/: \"the main port of entry from the Continent. The heyday of the town was in the 2nd century\") - hedge it or drop it; The web check could not prove: The excavation that followed lasted eight weeks"}]'::jsonb),
    ('04982451-5603-41cb-957d-758925170c8e'::uuid, 'card_description', 'M''Daourouch sits at the site of the ancient Berber-Roman town of Madauros in Numidia. Two names, one piece of ground: Madauros for the ancient town, M''Daourouch for the site standing there.', NULL, 'teaser-card-s039:04982451-5603-41cb-957d-758925170c8e:card_description', 'teaser-card-s039 (card-clear-recheck-disputed): card cleared (recheck-disputed)', '||b875256f2e5eaec54f9491fcb0a0d9c4c44c7346f6cf982956bf20637fe026e2', '[{"source": "lane WB run wb-recheck-2026-10-24: recheck-disputed", "url": "output/remediation/teaser/runs/wb-recheck-2026-10-24/OUTCOMES.jsonl", "quote": "The web check finds the claim disputed (reputable sources disagree): M''Daourouch (a modern Algerian town) sits at the site of the ancient town of Madauros (https://faculty.georgetown.edu/jod/algeria/madauros-scenes.html: \"This page comprises images taken on the archaeological site of ancient Madauros, near modern Mdaourouch, Algeria\") - hedge it or drop it; The web check finds the claim disputed (reputable sources disagree): The ancient town and the modern place occupy one and the same piece of ground (https://fr.wikipedia.org/wiki/M%27daourouch: \"Son nom vient de l''antique ville romano-numide de Madauros, dont les vestiges se situent à quelques kilomètres\") - hedge it or drop it"}]'::jsonb),
    ('057ed947-18f5-45f5-b4c6-6bc1e29264d7'::uuid, 'card_description', 'On a spur of Dinedor Hill, Dinedor Camp looks east to where the Wye meets the Lugg. In 1951 a trench was cut from the rampart edge about 35 metres towards the centre of the camp.', NULL, 'teaser-card-s039:057ed947-18f5-45f5-b4c6-6bc1e29264d7:card_description', 'teaser-card-s039 (card-clear-recheck-disputed): card cleared (recheck-disputed)', '||c11691d806bfc1a97a8dc882aa7c438bb89932ffa908d7d25c672b2a9479ac35', '[{"source": "lane WB run wb-recheck-2026-10-24: recheck-disputed", "url": "output/remediation/teaser/runs/wb-recheck-2026-10-24/OUTCOMES.jsonl", "quote": "The web check finds the claim disputed (reputable sources disagree): The camp lies on a spur of Dinedor Hill (https://web.archive.org/web/20190203144218/http://hillforts.arch.ox.ac.uk/records/EN0013.html: \"Important contour hillfort located on the summit of Dinedor Hill overlooking the River Wye and Hereford\") - hedge it or drop it; The web check could not prove: The Wye-Lugg confluence lies to the east of the camp (the camp looks east to it); The web check could not prove: The 1951 trench ran about 35 metres"}]'::jsonb),
    ('05afa876-bd9b-4285-8aa3-cb1f71fb3707'::uuid, 'card_description', 'About 200 meters north of the Araz River, Ərəbyengicə is an ancient settlement whose finds include obsidian remains and combed-surface pottery of the Late Chalcolithic.', NULL, 'teaser-card-s039:05afa876-bd9b-4285-8aa3-cb1f71fb3707:card_description', 'teaser-card-s039 (card-clear-recheck-check-failed): card cleared (recheck-check-failed)', '||135cf7e5bf489d980eff31772a04bb146e0eda4754f3c25f1cec83eed1973936', '[{"source": "lane WB run wb-recheck-2026-10-24: recheck-check-failed", "url": "output/remediation/teaser/runs/wb-recheck-2026-10-24/OUTCOMES.jsonl", "quote": "No sentence of the description supports the claim: the combed-surface pottery is of (dates to) the Late Chalcolithic; S3 says the combed-surface ceramics are ''typical of the Late Chalcolithic of the Nakhchivan region''; the card drops ''typical of'' and makes them pottery of the Late Chalcolithic - keep the qualifier, e.g. ''combed-surface pottery typical of the Late Chalcolithic''."}]'::jsonb),
    ('06a44374-50d9-4bc1-b747-41fa09e28eee'::uuid, 'card_description', 'Near the village of Ninamaca, about 30 chullpas of pre-Inca times stand on top of a mountain at about 3,000 m. Ninamarca is possibly Quechua nina, fire, and marka, village: fire village.', NULL, 'teaser-card-s039:06a44374-50d9-4bc1-b747-41fa09e28eee:card_description', 'teaser-card-s039 (card-clear-recheck-disputed): card cleared (recheck-disputed)', '||e4830f5c5c4a3c8a747fec5a44aec0542f2d6ae5195d3b952b04c1f42c1dc062', '[{"source": "lane WB run wb-recheck-2026-10-24: recheck-disputed", "url": "output/remediation/teaser/runs/wb-recheck-2026-10-24/OUTCOMES.jsonl", "quote": "The web check finds the claim disputed (reputable sources disagree): The site is at about 3,000 m altitude (https://perujungletrips.com/chullpas-of-ninamarca-pre-inca-funerary-towers-on-the-way-to-manu/: \"Their altitude is approximately 3,600 meters (11,811 ft) above sea level.\") - hedge it or drop it"}]'::jsonb),
    ('07947420-54ee-4cf5-ac06-47814ce7f56d'::uuid, 'card_description', 'Digging for a ferret in 1864, a gamekeeper uncovered Chedworth Roman Villa, one of the largest Roman villas found in Britain. Its west wing held a mosaic dining-room and two bathing suites.', NULL, 'teaser-card-s039:07947420-54ee-4cf5-ac06-47814ce7f56d:card_description', 'teaser-card-s039 (card-clear-recheck-check-failed): card cleared (recheck-check-failed)', '||e614182c03b2b04143807fc6b4bd3221add4f8916c705a6293a04347d698f6db', '[{"source": "lane WB run wb-recheck-2026-10-24: recheck-check-failed", "url": "output/remediation/teaser/runs/wb-recheck-2026-10-24/OUTCOMES.jsonl", "quote": "No sentence of the description supports the claim: its west wing held two bathing suites; S4 says the 4th-century building included a west wing with the mosaic dining-room ''as well as two separate bathing suites''; it does not say the bathing suites were in the west wing - attribute the two bathing suites to the villa''s 4th-century building, not to the west wing."}]'::jsonb),
    ('0cf46f86-7eea-46ec-bf6c-b803d3145000'::uuid, 'card_description', 'Four faces, four passages: the Arch of Janus is the only surviving quadrifrons arch in Rome, 16 m high in the Forum Boarium. Built from older spolia, it may honor Constantine I.', NULL, 'teaser-card-s039:0cf46f86-7eea-46ec-bf6c-b803d3145000:card_description', 'teaser-card-s039 (card-clear-recheck-check-failed): card cleared (recheck-check-failed)', '||03a954825bf53398e84ada6ceee6c9c0e8e2ae1a748dfc3445079badd40c7b4d', '[{"source": "lane WB run wb-recheck-2026-10-24: recheck-check-failed", "url": "output/remediation/teaser/runs/wb-recheck-2026-10-24/OUTCOMES.jsonl", "quote": "No sentence of the description supports the claim: it may honor Constantine I (as the only named candidate); S2 says the arch may honor Constantine I or Constantius II; the card names only Constantine I, presenting him as the sole candidate - keep both alternatives, e.g. ''it may honor Constantine I or Constantius II''."}]'::jsonb),
    ('0d801018-7183-44a3-97e4-136aa8a374ce'::uuid, 'card_description', 'Guellayhuasin is an archaeological site in Peru''s Pasco region, at an elevation of 3,167 m, northwest of the village of Pallanchacra. High Pasco ground, and a site marked out on it.', NULL, 'teaser-card-s039:0d801018-7183-44a3-97e4-136aa8a374ce:card_description', 'teaser-card-s039 (card-clear-recheck-check-failed): card cleared (recheck-check-failed)', '||06684554ce7dc5ba6534fb1f13f0cc6cdee1cb951d9ac5c9836a6cd4d300cd1c', '[{"source": "lane WB run wb-recheck-2026-10-24: recheck-check-failed", "url": "output/remediation/teaser/runs/wb-recheck-2026-10-24/OUTCOMES.jsonl", "quote": "No sentence of the description supports the claim: the site is marked out on that ground; No sentence says the site is ''marked out'' on the ground; drop ''and a site marked out on it'' and add nothing the description does not say."}]'::jsonb),
    ('0d938cf2-c77d-4741-83cb-c3413761d2c1'::uuid, 'card_description', 'Inside the Chiltern Hills, Ivinghoe keeps an Anglo-Saxon name glossed as ''Ifa''s hill-spur''. In 1086 the Domesday Book wrote it Evinghehou, and St Mary was burnt in 1234, rebuilt in 1241.', NULL, 'teaser-card-s039:0d938cf2-c77d-4741-83cb-c3413761d2c1:card_description', 'teaser-card-s039 (card-clear-recheck-check-failed): card cleared (recheck-check-failed)', '||ec738fe4160c02f4e82bc55f99d7d54fcc0310239471c9049705f771f5f70416', '[{"source": "lane WB run wb-recheck-2026-10-24: recheck-check-failed", "url": "output/remediation/teaser/runs/wb-recheck-2026-10-24/OUTCOMES.jsonl", "quote": "The card writes ''St Mary was burnt in 1234'', which reads as the saint being burnt; name the parish church of St Mary the Virgin, as S6 does."}]'::jsonb),
    ('0eaedf34-031e-4b8f-8fff-2db84a3e6da6'::uuid, 'card_description', 'Two monuments stand in the townland of Moylehid, County Fermanagh: the Eagle''s Knoll Cairn passage tomb and the Moylehid ring cairn, named from the Irish Mul-leithid, hill of breadth.', NULL, 'teaser-card-s039:0eaedf34-031e-4b8f-8fff-2db84a3e6da6:card_description', 'teaser-card-s039 (card-clear-recheck-contradicted): card cleared (recheck-contradicted)', '||8e5b2162c114636902a3e8247531a3961ba81edbe2db6db299db6e9f60cfd45e', '[{"source": "lane WB run wb-recheck-2026-10-24: recheck-contradicted", "url": "output/remediation/teaser/runs/wb-recheck-2026-10-24/OUTCOMES.jsonl", "quote": "The web check contradicts: Two monuments stand in the townland of Moylehid (https://www.archaeopress.com/Archaeopress/DMS/F1DF8BF6D0F94A75A36A5771AD076152/9781784910068-sample.pdf: \"Moylehid Court Tomb (FER 210:051)\")"}]'::jsonb),
    ('0f7c84f4-7364-434d-b003-706c8d7a3275'::uuid, 'card_description', 'Cattle, deer, pig and goat bones lay beside the ceramics at Alampra, a Middle Bronze Age settlement of circa 1900-1650 BC in Cyprus, dug by John E. Coleman between 1974 and 1985.', NULL, 'teaser-card-s039:0f7c84f4-7364-434d-b003-706c8d7a3275:card_description', 'teaser-card-s039 (card-clear-recheck-disputed): card cleared (recheck-disputed)', '||ca2e091135a88c0cb26d90267513065f01dfa83e424305010553c507502ea872', '[{"source": "lane WB run wb-recheck-2026-10-24: recheck-disputed", "url": "output/remediation/teaser/runs/wb-recheck-2026-10-24/OUTCOMES.jsonl", "quote": "The web check finds the claim disputed (reputable sources disagree): The settlement dates to circa 1900-1650 BC (https://www.ancientcyprus.com/sites/alambra: \"so the village was abandoned \"no later than ca. 1800 B.C.\"\") - hedge it or drop it; The web check could not prove: Pig bones were found there"}]'::jsonb),
    ('1758f6e8-4518-43fb-a14a-1ce52caca683'::uuid, 'card_description', 'By the EX-214 road, the Dolmen del prado de Lácara was built toward the end of the 4th millennium BC, or in the early 3rd millennium BC, among Extremadura''s most monumental megalithic sites.', NULL, 'teaser-card-s039:1758f6e8-4518-43fb-a14a-1ce52caca683:card_description', 'teaser-card-s039 (card-clear-recheck-adversarial-failed): card cleared (recheck-adversarial-failed)', '||9e9a31ee0c67fd81498fdcf84ec59ae6d09fd263f4465a3d79e592bb27eb152e', '[{"source": "lane WB run wb-recheck-2026-10-24: recheck-adversarial-failed", "url": "output/remediation/teaser/runs/wb-recheck-2026-10-24/OUTCOMES.jsonl", "quote": "No sentence of the description supports the claim: as worded (''was built ... among Extremadura''s most monumental megalithic sites''), it was built amid a group of other monumental megalithic sites; The sentence attaches ''among Extremadura''s most monumental megalithic sites'' to ''was built'', so it reads as if the dolmen was built amid other monumental megaliths, which no sentence says and the site''s own Wikipedia article (https://en.wikipedia.org/wiki/Dolmen_del_prado_de_L%C3%A1cara) contradicts: ''the closest dolmens, such as Carmonita or Cueva del Monje, are between 13 and 15 km away''; reword so the ranking stands on its own, e.g. ''... and it ranks among Extremadura''s most monumental megalithic sites''."}]'::jsonb),
    ('184dfea2-b710-4c3a-a3e8-d8cea0738290'::uuid, 'card_description', 'On top of the mountain Allqu Willka in Ayacucho, Inka Raqay is an Inca site, and raqay in Quechua means a ruin, a shed, a storehouse, or a dormitory for farm laborers.', NULL, 'teaser-card-s039:184dfea2-b710-4c3a-a3e8-d8cea0738290:card_description', 'teaser-card-s039 (card-clear-recheck-unproven): card cleared (recheck-unproven)', '||c605305505a5ed1cec9975ef4d7b7a6576b32e1f844ade6e307670ddf7c6c2b9', '[{"source": "lane WB run wb-recheck-2026-10-24: recheck-unproven", "url": "output/remediation/teaser/runs/wb-recheck-2026-10-24/OUTCOMES.jsonl", "quote": "The web check could not prove: In Quechua, raqay means a storehouse; The web check could not prove: In Quechua, raqay means a dormitory for farm laborers"}]'::jsonb),
    ('19aa5815-9965-43b3-a2d9-e35190fd50ec'::uuid, 'card_description', 'Gran Saposoa: ruins in the Andean cloud forests, brought to attention by Gene Savoy in 1999. Scholars dispute his claims: Muscutt and Schjellerup had located them in the mid-1990s.', NULL, 'teaser-card-s039:19aa5815-9965-43b3-a2d9-e35190fd50ec:card_description', 'teaser-card-s039 (card-clear-recheck-contradicted): card cleared (recheck-contradicted)', '||d742040eaca72813b20aef9c925a9a8aa3911efd7b411a0bab86cc9ad894b9cd', '[{"source": "lane WB run wb-recheck-2026-10-24: recheck-contradicted", "url": "output/remediation/teaser/runs/wb-recheck-2026-10-24/OUTCOMES.jsonl", "quote": "The web check contradicts: Muscutt and Schjellerup located the ruins in the mid-1990s (https://dokumen.pub/federico-kauffman-doig-the-chachapoyas-culture.html: \"this site is composed of more than 400 structures (Photo courtesy of Anselmo Lozano). It has been studied in detail by Keith Muscutt (1988)\")"}]'::jsonb),
    ('19e287b4-3f69-4145-8f8e-4e214d8bb954'::uuid, 'card_description', 'An Iron Age hill fort 3 miles north west of Wiveliscombe: Clatworthy Camp is an Ancient Monument on the Heritage at Risk Register, vulnerable to scrub and tree growth.', NULL, 'teaser-card-s039:19e287b4-3f69-4145-8f8e-4e214d8bb954:card_description', 'teaser-card-s039 (card-clear-recheck-disputed): card cleared (recheck-disputed)', '||b75f4d9b1317bd61d495a8872d9a5b485c1a65358baf04d5edb751c19a495520', '[{"source": "lane WB run wb-recheck-2026-10-24: recheck-disputed", "url": "output/remediation/teaser/runs/wb-recheck-2026-10-24/OUTCOMES.jsonl", "quote": "The web check could not prove: It lies 3 miles from Wiveliscombe; The web check finds the claim disputed (reputable sources disagree): It is (currently) on the Heritage at Risk Register (https://web.archive.org/web/20160923054354/https://www.wessexwater.co.uk/Cutting-at-Clatworthy/: \"Historic England were so satisfied with the progress that the hillfort is now likely to be removed from the Heritage At Risk Register.\") - hedge it or drop it"}]'::jsonb),
    ('1ae9f44c-ebe7-454c-8c55-58efe28c0376'::uuid, 'card_description', 'Destroyed by earthquake around 1700 BC, the Minoan temple of Anemospilia on Mount Juktas held a young man on an altar with a bronze blade, read as sacrifice, still debated.', NULL, 'teaser-card-s039:1ae9f44c-ebe7-454c-8c55-58efe28c0376:card_description', 'teaser-card-s039 (card-clear-recheck-disputed): card cleared (recheck-disputed)', '||b443dde32d88265b4fd96648b7f32551e481f49552011752a963dc10df5d4e21', '[{"source": "lane WB run wb-recheck-2026-10-24: recheck-disputed", "url": "output/remediation/teaser/runs/wb-recheck-2026-10-24/OUTCOMES.jsonl", "quote": "The web check finds the claim disputed (reputable sources disagree): The structure he lay on was an altar (http://www.minoancrete.com/anemospilia.htm: \"This body was found lying on what the excavator claimed was a low altar-like construction.\") - hedge it or drop it"}]'::jsonb),
    ('1bc1ab56-9d6f-478e-a4aa-76bdd91f61ee'::uuid, 'card_description', 'Quriwayrachina, an Inca-period site in Peru''s Ayacucho Region, keeps two platforms, Hatun Quri Wayrachina and Huch''uy Quri Wayrachina, near the mountain Inka Pallanka, venerated as an apu.', NULL, 'teaser-card-s039:1bc1ab56-9d6f-478e-a4aa-76bdd91f61ee:card_description', 'teaser-card-s039 (card-clear-recheck-unproven): card cleared (recheck-unproven)', '||0e24f64393da7af7a3c66ca091e09d5f17d3b8230dd9d8fcddb78cdbf681ec73', '[{"source": "lane WB run wb-recheck-2026-10-24: recheck-unproven", "url": "output/remediation/teaser/runs/wb-recheck-2026-10-24/OUTCOMES.jsonl", "quote": "The web check could not prove: The site dates to the Inca period; The web check could not prove: It has two platforms; The web check could not prove: The platforms are called Hatun Quri Wayrachina and Huch''uy Quri Wayrachina"}]'::jsonb),
    ('1e8b10e4-1124-4f35-9557-27a57d7dc4a1'::uuid, 'card_description', 'Along the old road from Methone to Dion, the Necropolises of Pydna hold Macedonian tombs from the Bronze Age to the early Christian period; smaller tumuli are lost to erosion.', NULL, 'teaser-card-s039:1e8b10e4-1124-4f35-9557-27a57d7dc4a1:card_description', 'teaser-card-s039 (card-clear-recheck-check-failed): card cleared (recheck-check-failed)', '||6f3072a02c41cd70ddca7f85cb361756258702f1241e359f85664b275e22ddb0', '[{"source": "lane WB run wb-recheck-2026-10-24: recheck-check-failed", "url": "output/remediation/teaser/runs/wb-recheck-2026-10-24/OUTCOMES.jsonl", "quote": "No sentence of the description supports the claim: the Macedonian tombs date from the Bronze Age to the early Christian period; S2 dates the burial sites as a whole from the Bronze Age to the early Christian period, not the Macedonian tombs; the card attaches that range to the Macedonian tombs - say instead that the burials range from the Bronze Age to the early Christian period."}]'::jsonb),
    ('1ef25b31-5c42-4ee6-aae1-1bd9c2640bff'::uuid, 'card_description', 'Near the Areni village along the Arpa River, Areni-1 Cave gave up the earliest known shoe in the world, the oldest humanoid brain, and a straw skirt dating to 3,900 years BCE.', NULL, 'teaser-card-s039:1ef25b31-5c42-4ee6-aae1-1bd9c2640bff:card_description', 'teaser-card-s039 (card-clear-recheck-contradicted): card cleared (recheck-contradicted)', '||abea90530c870eafc5e434d5316ac1e7db0a38bca95d7db8d58ccb482ea1d6ce', '[{"source": "lane WB run wb-recheck-2026-10-24: recheck-contradicted", "url": "output/remediation/teaser/runs/wb-recheck-2026-10-24/OUTCOMES.jsonl", "quote": "The web check contradicts: That shoe is the earliest known shoe in the world (https://www.worldhistory.org/Areni_Cave/: \"While not the oldest shoe in the world, it is the world''s oldest leather shoe.\"); The web check contradicts: That brain is the oldest humanoid brain (https://www.sciencealert.com/12000-year-old-preserved-human-brains-defy-soft-tissue-decay-assumptions: \"a team of scientists has identified more than 4,400 preserved human brains, dating back as far as 12,000 years ago\")"}]'::jsonb),
    ('20f12dcd-f2a7-4014-9dce-160c90b27749'::uuid, 'card_description', 'A Roman road ran from Poetovio in the north to Siscia in the south, and Pyrri stood along it in Pannonia. Evidence suggests the settlement lies under the village of Komin today.', NULL, 'teaser-card-s039:20f12dcd-f2a7-4014-9dce-160c90b27749:card_description', 'teaser-card-s039 (card-clear-recheck-check-failed): card cleared (recheck-check-failed)', '||664e7cf3be5ac96e4905d94f73f4059718009e51a7d1df168049700782dccbdd', '[{"source": "lane WB run wb-recheck-2026-10-24: recheck-check-failed", "url": "output/remediation/teaser/runs/wb-recheck-2026-10-24/OUTCOMES.jsonl", "quote": "No sentence of the description supports the claim: evidence suggests the settlement''s remains lie under the present-day village of Komin; S2 says only that the settlement''s location corresponds to the present-day village of Komin; ''lies under the village of Komin'' adds that its remains are buried beneath the village - say instead that evidence suggests it stood where the village of Komin is today."}]'::jsonb),
    ('217706bc-155b-44ca-bd4b-9df96e3bc014'::uuid, 'card_description', 'Kʼaxob was a Maya site in Belize, occupied from about 800 BC to AD 900. It began as a village and grew through the Early to Late Classic Periods into household mounds and plazas.', NULL, 'teaser-card-s039:217706bc-155b-44ca-bd4b-9df96e3bc014:card_description', 'teaser-card-s039 (card-clear-recheck-check-failed): card cleared (recheck-check-failed)', '||7b93b9147171eb038e1065eb8d465dd48d152ef4362f1f6e2e3f42f95391184c', '[{"source": "lane WB run wb-recheck-2026-10-24: recheck-check-failed", "url": "output/remediation/teaser/runs/wb-recheck-2026-10-24/OUTCOMES.jsonl", "quote": "No sentence of the description supports the claim: the Early to Late Classic growth is what produced the household mounds and plazas (the village grew into them); No sentence says the household mounds and plazas resulted from the Early to Late Classic expansion: S2 says only that the site expanded then and S4 that the complex includes them, so state the two facts separately instead of saying the village grew into the mounds and plazas."}]'::jsonb),
    ('21d9af3d-9d4e-4df0-beb1-268486146a61'::uuid, 'card_description', 'In the Ayacucho Region of Peru, Hatun Usnu means big usnu in Quechua: a pyramid-shaped, terraced ceremonial platform the Incas used for rituals involving liquid offerings.', NULL, 'teaser-card-s039:21d9af3d-9d4e-4df0-beb1-268486146a61:card_description', 'teaser-card-s039 (card-clear-recheck-unproven): card cleared (recheck-unproven)', '||b75eb1bf653714b8ec2d9d1e633d61449c01708d83d29dde437e176c45ff317d', '[{"source": "lane WB run wb-recheck-2026-10-24: recheck-unproven", "url": "output/remediation/teaser/runs/wb-recheck-2026-10-24/OUTCOMES.jsonl", "quote": "The web check could not prove: Hatun Usnu is an archaeological site (a ceremonial platform) in the Ayacucho Region of Peru; The web check could not prove: Hatun Usnu itself is pyramid-shaped and terraced; The web check could not prove: The Incas used Hatun Usnu itself for rituals with liquid offerings"}]'::jsonb),
    ('2726f1bb-9af6-4f23-af79-fc0f789a5ddc'::uuid, 'card_description', 'At the end of the 1-mile-long crag of the Whin Sill, Hadrian''s Wall runs over the fort at Housesteads, whose stone walls were built around AD 124 above a demolished turret.', NULL, 'teaser-card-s039:2726f1bb-9af6-4f23-af79-fc0f789a5ddc:card_description', 'teaser-card-s039 (card-clear-recheck-check-failed): card cleared (recheck-check-failed)', '||718dfe9f3b5cec0f3307e1beed135b677b1887ad8ce8d26875c4fe63c2fa205c', '[{"source": "lane WB run wb-recheck-2026-10-24: recheck-check-failed", "url": "output/remediation/teaser/runs/wb-recheck-2026-10-24/OUTCOMES.jsonl", "quote": "No sentence of the description supports the claim: Hadrian''s Wall runs over the fort at Housesteads; No sentence says Hadrian''s Wall runs over the fort: S2 says the Wall runs over the crag, and S5 says the fort''s northern wall overlies the original Broad Wall foundation, so rephrase to say the fort sits on the end of the crag over which the Wall runs."}]'::jsonb),
    ('28fbf63d-5ca4-45fd-a54e-7a660232b148'::uuid, 'card_description', 'KaʼKabish lies in Belize''s Orange Walk District, near Lamanai, El Pozito and Blue Creek. Three neighbouring places, and the district in Belize that holds the site.', NULL, 'teaser-card-s039:28fbf63d-5ca4-45fd-a54e-7a660232b148:card_description', 'teaser-card-s039 (card-clear-recheck-check-failed): card cleared (recheck-check-failed)', '||19159553826b31fd38de01f857747b16e027bceb06106e0374fac559f5d4b73a', '[{"source": "lane WB run wb-recheck-2026-10-24: recheck-check-failed", "url": "output/remediation/teaser/runs/wb-recheck-2026-10-24/OUTCOMES.jsonl", "quote": "The tone rules are broken (see the checker''s reasons).; The second sentence (''Three neighbouring places, and the district in Belize that holds the site.'') is a verbless fragment that only restates the first sentence; it is filler, not an evocative teaser line - drop it or replace it with a tone-only line that adds no claim."}]'::jsonb),
    ('2c437fa8-96cf-4451-b949-7e5c09889802'::uuid, 'card_description', 'A local landowner uncovered Huaca Esmeralda from the sand in 1923; the Chimu pyramid in Trujillo shows relief of fishing nets and fish on two platforms of approximately 65 by 41 meters.', NULL, 'teaser-card-s039:2c437fa8-96cf-4451-b949-7e5c09889802:card_description', 'teaser-card-s039 (card-clear-recheck-check-failed): card cleared (recheck-check-failed)', '||54cb40b6988dd10ddecc11ec0c52c64896586aaebcbf1959aadc94568d9a695d', '[{"source": "lane WB run wb-recheck-2026-10-24: recheck-check-failed", "url": "output/remediation/teaser/runs/wb-recheck-2026-10-24/OUTCOMES.jsonl", "quote": "No sentence of the description supports the claim: the landowner uncovered (dug out) the site from the sand; S4 says the landowner discovered the buried site in 1923, not that he uncovered it from the sand; write ''discovered beneath the sand'' rather than ''uncovered ... from the sand''."}]'::jsonb),
    ('2cabb7a1-0596-457c-b37f-c041440b4fe2'::uuid, 'card_description', 'On the southwest slope of the Acropolis of Athens, the stone Odeon of Herodes Atticus was completed in AD 161. Its stands and orchestra were restored in Pentelic marble in the 1950s.', NULL, 'teaser-card-s039:2cabb7a1-0596-457c-b37f-c041440b4fe2:card_description', 'teaser-card-s039 (card-clear-recheck-contradicted): card cleared (recheck-contradicted)', '||e848597824a17c704b110806cbbdaf089eb6ccee558d514ded1b1942199f867b', '[{"source": "lane WB run wb-recheck-2026-10-24: recheck-contradicted", "url": "output/remediation/teaser/runs/wb-recheck-2026-10-24/OUTCOMES.jsonl", "quote": "The web check finds the claim disputed (reputable sources disagree): It was completed in AD 161 (https://athensattica.com/el/point/odeio-hrodou-attikou-hrodeio/: \"Δεν είναι γνωστή η ακριβής χρονολογία της κατασκευής του, αλλά είναι σίγουρο ότι αυτό συνέβη ανάμεσα στη χρονολογία θανάτου της Ρήγιλλας και το 174\") - hedge it or drop it; The web check contradicts: Its orchestra was restored in Pentelic marble (https://diazoma.gr/theaters/%CF%89%CE%B4%CE%B5%CE%AF%CE%BF-%CE%B7%CF%81%CF%8E%CE%B4%CE%BF%CF%85-%CF%84%CE%BF%CF%85-%CE%B1%CF%84%CF%84%CE%B9%CE%BA%CE%BF%CF%8D/: \"Η ημικυκλική ορχήστρα είχε επίστρωση από χρωματιστά μάρμαρα, που ανακατασκευάστηκαν στους νεώτερους χρόνους.\")"}]'::jsonb),
    ('2da0bfc3-cc20-444a-bfa7-bf23642ecb0b'::uuid, 'card_description', 'On the Desna River bank, Mezine holds Ukraine''s most Paleolithic artifact finds: bracelets engraved with marks possibly marking lunar cycles, and the earliest known meander pattern.', NULL, 'teaser-card-s039:2da0bfc3-cc20-444a-bfa7-bf23642ecb0b:card_description', 'teaser-card-s039 (card-clear-recheck-adversarial-failed): card cleared (recheck-adversarial-failed)', '||e469b1837bc238c46c43f03a926784111d4643f1779bcfcc76e5a729f16fc7a6', '[{"source": "lane WB run wb-recheck-2026-10-24: recheck-adversarial-failed", "url": "output/remediation/teaser/runs/wb-recheck-2026-10-24/OUTCOMES.jsonl", "quote": "No sentence of the description supports the claim: The site holds these finds (the engraved bracelets and the meander-patterned object) today; The card''s present tense ''Mezine holds ...: bracelets ... and the earliest known meander pattern'' says the objects are at the site today, which S3 and S4 do not say (they say the bracelets and the meander object were found or discovered there), and the Internet Encyclopedia of Ukraine (https://www.encyclopediaofukraine.com/display.asp?linkpath=pages%5CM%5CI%5CMizynarcheologicalsite.htm) states ''The collection is now housed in Kyiv at the Archeological Museum'' - rewrite as ''has yielded'' or ''finds from Mezine include'' instead of ''holds''."}]'::jsonb),
    ('2e547c1d-6f33-4342-b285-69b46d4a0b6e'::uuid, 'card_description', 'On the Piano di Tirena hill in Calabria, Terina lies between the Savuto and the Grande and matches a description Strabo wrote around 20 AD. Its coins and inscriptions rest in Lamezia Terme.', NULL, 'teaser-card-s039:2e547c1d-6f33-4342-b285-69b46d4a0b6e:card_description', 'teaser-card-s039 (card-clear-recheck-check-failed): card cleared (recheck-check-failed)', '||8abf4fb0c8dd1214f9ae330b67ad6569812361f6d88dc8547d977e086de7babc', '[{"source": "lane WB run wb-recheck-2026-10-24: recheck-check-failed", "url": "output/remediation/teaser/runs/wb-recheck-2026-10-24/OUTCOMES.jsonl", "quote": "No sentence of the description supports the claim: the city''s coins and inscriptions (as a whole) are kept in Lamezia Terme; S3 says only that coins, inscriptions and other artefacts retrieved from the site (in the investigation from 1997) can be seen in the Museo Archeologico Lametino; ''Its coins and inscriptions rest in Lamezia Terme'' drops that restriction and implies all of Terina''s coins and inscriptions are there - write ''coins and inscriptions found at the site''."}]'::jsonb),
    ('3191f287-4b47-4d83-903f-9815001086ed'::uuid, 'card_description', 'At Nausharo, 6 km from Mehrgarh, a pottery workshop gave up fired and unfired pottery, unworked clay and 12 flint blades or blade fragments, plus copper traces on two blade platforms.', NULL, 'teaser-card-s039:3191f287-4b47-4d83-903f-9815001086ed:card_description', 'teaser-card-s039 (card-clear-recheck-contradicted): card cleared (recheck-contradicted)', '||95f494165eb0a09014a9cc6780d227b29196a38f5e2d67950b892ed16a9ac964', '[{"source": "lane WB run wb-recheck-2026-10-24: recheck-contradicted", "url": "output/remediation/teaser/runs/wb-recheck-2026-10-24/OUTCOMES.jsonl", "quote": "The web check could not prove: The workshop yielded fired pottery; The web check could not prove: The workshop yielded unworked clay; The web check could not prove: The workshop yielded 12 flint blades or blade fragments; The web check contradicts: Copper traces were found on the platforms of two blades (https://www.academia.edu/17712376/A_pottery_workshop_with_flint_tools_on_blades_knapped_with_copper_at_Nausharo_Indus_civilisation_ca_2500_BC_: \"Blade n. 136 (b) shows no trace of metallic nodules.\")"}]'::jsonb),
    ('32a2b3eb-c4c3-4574-bbf5-30a4d7a68dfc'::uuid, 'card_description', 'In 1951 a quarry explosion exposed the Cave of Maltravieso in Caceres. Inside, 71 hands were stencilled onto the walls, together with linear designs and animal paintings.', NULL, 'teaser-card-s039:32a2b3eb-c4c3-4574-bbf5-30a4d7a68dfc:card_description', 'teaser-card-s039 (card-clear-recheck-disputed): card cleared (recheck-disputed)', '||dc396b33415e3ea3d37619c1cac4f849d685c64975f06065a72f895d618fc9fe', '[{"source": "lane WB run wb-recheck-2026-10-24: recheck-disputed", "url": "output/remediation/teaser/runs/wb-recheck-2026-10-24/OUTCOMES.jsonl", "quote": "The web check finds the claim disputed (reputable sources disagree): 71 hands were stencilled onto the cave walls (https://www.bradshawfoundation.com/hands/secrets_of_prehistoric_hand_paintings/index.php: \"investigating the 57 hand stencils\") - hedge it or drop it"}]'::jsonb),
    ('33f2b3eb-5fe2-444d-8168-807b81e17f2b'::uuid, 'card_description', 'Carn Brea, 1.6 km southwest of Redruth, crowns a hilltop in Cornwall, a fortified Neolithic settlement occupied between 3700 and 3400 BC, ringed by a 4.5-hectare outer rampart.', NULL, 'teaser-card-s039:33f2b3eb-5fe2-444d-8168-807b81e17f2b:card_description', 'teaser-card-s039 (card-clear-recheck-unproven): card cleared (recheck-unproven)', '||1181e74768251dbf1dd91363edb71003a882acb0c9a52eadb29083a38823940d', '[{"source": "lane WB run wb-recheck-2026-10-24: recheck-unproven", "url": "output/remediation/teaser/runs/wb-recheck-2026-10-24/OUTCOMES.jsonl", "quote": "The web check could not prove: Carn Brea lies 1.6 km from Redruth; The web check could not prove: The outer rampart encloses 4.5 hectares"}]'::jsonb),
    ('360da20f-8f95-4ba9-83fc-49d4b193b679'::uuid, 'card_description', 'Three sinkholes drop natural light into the nine chambers of the larger Padah-Lin cave. In the smaller rock shelter, red ochre hands, fish, bulls and bison mark the rock.', NULL, 'teaser-card-s039:360da20f-8f95-4ba9-83fc-49d4b193b679:card_description', 'teaser-card-s039 (card-clear-recheck-contradicted): card cleared (recheck-contradicted)', '||1437d42b2a17af3a03d51f189744da2005fc474b87d67940d70b14ec44e27a83', '[{"source": "lane WB run wb-recheck-2026-10-24: recheck-contradicted", "url": "output/remediation/teaser/runs/wb-recheck-2026-10-24/OUTCOMES.jsonl", "quote": "The web check contradicts: Three sinkholes let natural light into the larger cave (https://scholarspace.manoa.hawaii.edu/server/api/core/bitstreams/33f26f7f-2c88-4667-aa5d-594810000fd5/content: \"the interior of the whole cave would be pitch dark but for the sinkholes or apertures in the roofs of four caverns, through which openings sunlight and fresh air penetrate\")"}]'::jsonb),
    ('37999fa3-d22d-4c51-a2f5-fa0dd9d82942'::uuid, 'card_description', 'El Baúl, part of the Cotzumalhuapa Archaeological Zone, was occupied during the Formative stage; its southern acropolis was destroyed in 1997 and its main groups now lie under sugar cane.', NULL, 'teaser-card-s039:37999fa3-d22d-4c51-a2f5-fa0dd9d82942:card_description', 'teaser-card-s039 (card-clear-recheck-contradicted): card cleared (recheck-contradicted)', '||6ab84b560e2dff511cd65a597b6c3f05654dc2cbcfaeba6c599d02f5b3a6c429', '[{"source": "lane WB run wb-recheck-2026-10-24: recheck-contradicted", "url": "output/remediation/teaser/runs/wb-recheck-2026-10-24/OUTCOMES.jsonl", "quote": "The web check contradicts: Its southern acropolis was destroyed (https://www.mesoweb.com/Simposio/pdf/11/Chinchilla.1998.pdf: \"El muro sur del Gran Recinto se ha visto muy afectado por la construcción de casas en el último año y ha perdido buena parte de su altura original\"); The web check contradicts: The destruction happened in 1997 (https://www.mesoweb.com/Simposio/pdf/11/Chinchilla.1998.pdf: \"En 1996, el sitio de El Baúl fue severamente afectado por una lotificación\"); The web check could not prove: Its main groups now lie under sugar cane"}]'::jsonb),
    ('38aefc7c-1eb9-42d2-bd76-8d6b70847e35'::uuid, 'card_description', 'Kuélap stands on a limestone ridge at 3000 metres, its walls 10 to 20 m high and all but five of its 421 structures circular. It was rediscovered in 1843 by Juan Crisóstomo Nieto.', NULL, 'teaser-card-s039:38aefc7c-1eb9-42d2-bd76-8d6b70847e35:card_description', 'teaser-card-s039 (card-clear-recheck-disputed): card cleared (recheck-disputed)', '||bfc1d3152610d54b91be1bbbbbbbe6b8b2388ebaadcab89b1be7517688fee9bc', '[{"source": "lane WB run wb-recheck-2026-10-24: recheck-disputed", "url": "output/remediation/teaser/runs/wb-recheck-2026-10-24/OUTCOMES.jsonl", "quote": "The web check finds the claim disputed (reputable sources disagree): Kuélap has 421 structures (https://popular-archaeology.com/article/warriors-of-the-clouds-kuelap-a-chachapoya-citadel/: \"over five hundred densely packed structures enclosed by the site’s outer wall\") - hedge it or drop it; The web check finds the claim disputed (reputable sources disagree): All but five of its structures are circular (https://scholarworks.utrgv.edu/cgi/viewcontent.cgi?article=1023&context=art_fac: \"Three of Kuelap’s four rectangular structures are located in the upper level.\") - hedge it or drop it"}]'::jsonb),
    ('3d68442a-8cd7-4679-8845-189db9470f27'::uuid, 'card_description', 'In northern Greece, Toumba is the Greek name for the mounds Bronze Age settlements left behind. What the settlements left in the ground, and the word the mounds carry.', NULL, 'teaser-card-s039:3d68442a-8cd7-4679-8845-189db9470f27:card_description', 'teaser-card-s039 (card-clear-recheck-check-failed): card cleared (recheck-check-failed)', '||fadbbc4117bb0748ff0664f0cfcc928fd0e441107b47e979e06c929705c937ed', '[{"source": "lane WB run wb-recheck-2026-10-24: recheck-check-failed", "url": "output/remediation/teaser/runs/wb-recheck-2026-10-24/OUTCOMES.jsonl", "quote": "No sentence of the description supports the claim: the settlements left something in the ground; The tone rules are broken (see the checker''s reasons).; The second sentence ''What the settlements left in the ground, and the word the mounds carry.'' is a verbless fragment that is not proper English and repeats the first sentence; replace it with a complete sentence drawn from S1 or drop it.; No sentence says the settlements left anything ''in the ground''; S1 says only that the settlements created mounds."}]'::jsonb),
    ('3dd0bac8-4618-4f61-a2b2-4dd229a76e45'::uuid, 'card_description', 'In a private front garden on the Islandmagee peninsula stands Ballylumford Dolmen, known locally as the Druid''s Altar: four upright stones under a heavy capstone, and a fallen stone inside.', NULL, 'teaser-card-s039:3dd0bac8-4618-4f61-a2b2-4dd229a76e45:card_description', 'teaser-card-s039 (card-clear-recheck-disputed): card cleared (recheck-disputed)', '||7374f93f01985ab640b6a3ac71c729a9d8d46fc4f91794f344d24b46320ad1e4', '[{"source": "lane WB run wb-recheck-2026-10-24: recheck-disputed", "url": "output/remediation/teaser/runs/wb-recheck-2026-10-24/OUTCOMES.jsonl", "quote": "The web check finds the claim disputed (reputable sources disagree): It has four upright stones. (https://www.megalithic.co.uk/article.php?sid=35587: \"The megalith consists of three angular basalt orthostats on which is set a substantial capstone which tilts down to the distal end.\") - hedge it or drop it"}]'::jsonb),
    ('3efdc2f9-61ef-40b9-8d93-0f61668d8418'::uuid, 'card_description', 'Approximately 1.6 km south-west of Clevedon in North Somerset, Wain''s Hill is an Iron Age bivallate hillfort: linear earthwork banks and ditches on steep slopes.', NULL, 'teaser-card-s039:3efdc2f9-61ef-40b9-8d93-0f61668d8418:card_description', 'teaser-card-s039 (card-clear-recheck-check-failed): card cleared (recheck-check-failed)', '||38a339439db656e9997e576a5f697fa052a04be26fba4edbf6cd0198e2972799', '[{"source": "lane WB run wb-recheck-2026-10-24: recheck-check-failed", "url": "output/remediation/teaser/runs/wb-recheck-2026-10-24/OUTCOMES.jsonl", "quote": "No sentence of the description supports the claim: the banks and ditches lie on steep slopes; Neither a sentence nor W1 puts the banks and ditches on steep slopes: S2 says the hill''s steep northern and southern slopes serve as natural defences, so describe the slopes as the natural defence rather than as the place of the earthworks."}]'::jsonb),
    ('3fe3b8d1-a2a0-4d11-8bed-68f33110fb57'::uuid, 'card_description', 'Strabo called Rudiae a Greek city. In the immediate outskirts of Lecce, its remains still show traces of an amphitheatre, a necropolis and two city walls built of tuff.', NULL, 'teaser-card-s039:3fe3b8d1-a2a0-4d11-8bed-68f33110fb57:card_description', 'teaser-card-s039 (card-clear-recheck-check-failed): card cleared (recheck-check-failed)', '||914e08dc11ac97b10b6f60d1f4e42186014f6e3515006a6f050d7dbf6a851a0f', '[{"source": "lane WB run wb-recheck-2026-10-24: recheck-check-failed", "url": "output/remediation/teaser/runs/wb-recheck-2026-10-24/OUTCOMES.jsonl", "quote": "No sentence of the description supports the claim: these remains are Rudiae''s (stated outright); S2 says only that Rudiae ''is identified with'' the remains outside Lecce; the card drops that attribution and calls them ''its remains'' outright - keep the identification, e.g. ''the remains identified with Rudiae''."}]'::jsonb),
    ('418f6d87-0fc3-4eb6-a310-e45a1fb43a3d'::uuid, 'card_description', 'The Asclepieion of Pergamon was a healing temple for Asclepius and Hygieia, founded in the mid-4th century BCE as a modest spring shrine and built up over roughly eight centuries.', NULL, 'teaser-card-s039:418f6d87-0fc3-4eb6-a310-e45a1fb43a3d:card_description', 'teaser-card-s039 (card-clear-recheck-contradicted): card cleared (recheck-contradicted)', '||05252a25bec69fe3b8d6687828e8549eda157708a6db14d604a4bbf731be3dce', '[{"source": "lane WB run wb-recheck-2026-10-24: recheck-contradicted", "url": "output/remediation/teaser/runs/wb-recheck-2026-10-24/OUTCOMES.jsonl", "quote": "The web check contradicts: It was built up over roughly eight centuries. (https://deepmappingsanctuaries.org/asklepieion-of-pergamon/: \"The final period is marked by the drastic transformation of the shrine during the reign of Hadrian.\")"}]'::jsonb),
    ('4656cc72-cea3-407e-a61c-314450ff6c62'::uuid, 'card_description', 'Dating to approximately 50 BC, Ringsbury Camp is an Iron Age multivallate hillfort whose double banks were built from non-local limestone rubble. Its inner bank rises 5 metres high.', NULL, 'teaser-card-s039:4656cc72-cea3-407e-a61c-314450ff6c62:card_description', 'teaser-card-s039 (card-clear-recheck-unproven): card cleared (recheck-unproven)', '||39089a066131efe1475323edc22f452479cf5377c15b7e915f096c9d9b905cba', '[{"source": "lane WB run wb-recheck-2026-10-24: recheck-unproven", "url": "output/remediation/teaser/runs/wb-recheck-2026-10-24/OUTCOMES.jsonl", "quote": "The web check could not prove: It dates to approximately 50 BC.; The web check could not prove: The banks were built from limestone rubble.; The web check could not prove: The limestone rubble of the banks is non-local."}]'::jsonb),
    ('46958435-223f-4648-93cc-153479b9c41c'::uuid, 'card_description', 'The Peterborough Petroglyphs, cut in the pre-Columbian era, are the largest collection of First Nations rock carvings in Ontario: shamans, animals, reptiles, possibly the Great Spirit.', NULL, 'teaser-card-s039:46958435-223f-4648-93cc-153479b9c41c:card_description', 'teaser-card-s039 (card-clear-recheck-check-failed): card cleared (recheck-check-failed)', '||704bf3befe393427f126850c258553779fb19f79f28bc17b56f27ad4013d497e', '[{"source": "lane WB run wb-recheck-2026-10-24: recheck-check-failed", "url": "output/remediation/teaser/runs/wb-recheck-2026-10-24/OUTCOMES.jsonl", "quote": "No sentence of the description supports the claim: they are the largest collection of First Nations rock carvings in Ontario (without the qualifier ''ancient''); S1 ranks the site as the largest collection of ancient First Nations petroglyphs in Ontario; the card drops ''ancient'' and so widens the ranking to all First Nations rock carvings - keep ''ancient'' in the superlative."}]'::jsonb),
    ('47c37ef9-98ee-41d8-879b-e78db06295da'::uuid, 'card_description', 'Phoenicians from Tyre revived Kition in the 9th century BC. Its Bamboula acropolis still shows ship sheds for triremes and a sanctuary dating to at least the 9th century BC.', NULL, 'teaser-card-s039:47c37ef9-98ee-41d8-879b-e78db06295da:card_description', 'teaser-card-s039 (card-clear-recheck-contradicted): card cleared (recheck-contradicted)', '||54d2adc1aa9602626183668fc75aa2d202d2e0fc109958caab063f99ca55c9fd', '[{"source": "lane WB run wb-recheck-2026-10-24: recheck-contradicted", "url": "output/remediation/teaser/runs/wb-recheck-2026-10-24/OUTCOMES.jsonl", "quote": "The web check contradicts: Bamboula was Kition''s acropolis (https://www.hisoma.mom.fr/recherche-et-activites/activites-de-terrain/programme-de-recherche-sur-chypre: \"était une motte artificielle recouvrant les niveaux antiques et non une acropole\")"}]'::jsonb),
    ('489ca9da-126d-463b-b792-a1b39a555e3e'::uuid, 'card_description', 'Treva is the historical name of a Roman-era settlement in Germany, first recorded by Claudius Ptolemy in the 2nd century AD. Under Augustus, Roman forces reached the Elbe.', NULL, 'teaser-card-s039:489ca9da-126d-463b-b792-a1b39a555e3e:card_description', 'teaser-card-s039 (card-clear-recheck-check-failed): card cleared (recheck-check-failed)', '||f2b89315e16f1b51d0bb29f53bcada6ab47651644355f5eba0a7def13ed99c3c', '[{"source": "lane WB run wb-recheck-2026-10-24: recheck-check-failed", "url": "output/remediation/teaser/runs/wb-recheck-2026-10-24/OUTCOMES.jsonl", "quote": "No sentence of the description supports the claim: the settlement is in Germany; No sentence places Treva in Germany; drop ''in Germany'' or keep only what S1 and S2 say."}]'::jsonb),
    ('4a07cc38-1b55-4254-b0ad-fe875310caf7'::uuid, 'card_description', 'The Temple of Augustus, probably built between 27 BC and AD 14, measures about 8 by 17.3 m and 14 m high, its tetrastyle prostyle porch of Corinthian columns standing on a podium.', NULL, 'teaser-card-s039:4a07cc38-1b55-4254-b0ad-fe875310caf7:card_description', 'teaser-card-s039 (card-clear-recheck-disputed): card cleared (recheck-disputed)', '||82a4bedb7bac8bc0fa07f4287fefaea2839b0754c045e038ae5b32e4e384b462', '[{"source": "lane WB run wb-recheck-2026-10-24: recheck-disputed", "url": "output/remediation/teaser/runs/wb-recheck-2026-10-24/OUTCOMES.jsonl", "quote": "The web check finds the claim disputed (reputable sources disagree): It is 14 m high (the Archaeological Museum of Istria, which runs the temple, gives 13.17 m) (https://www.ami-pula.hr/en/locations/temple-of-augustus/: \"The Temple of Augustus is 13.17 m high, 8.5 m wide, and 17.65 m long\") - hedge it or drop it"}]'::jsonb),
    ('4a1c0e1a-7ef6-4e1f-bbdb-6334304bcf52'::uuid, 'card_description', 'At Ras Shamra the port city of Ugarit held a royal palace of many courtyards and two acropolis temples to Baal and Dagan; its excavated texts echo Hebrew biblical poetry.', NULL, 'teaser-card-s039:4a1c0e1a-7ef6-4e1f-bbdb-6334304bcf52:card_description', 'teaser-card-s039 (card-clear-recheck-check-failed): card cleared (recheck-check-failed)', '||d2d30301c815ce3f09fb42abd65992fafa5ff1e7b2a2d7e3daa5bdd5608a7bd8', '[{"source": "lane WB run wb-recheck-2026-10-24: recheck-check-failed", "url": "output/remediation/teaser/runs/wb-recheck-2026-10-24/OUTCOMES.jsonl", "quote": "No sentence of the description supports the claim: the palace had many courtyards; S2 says the royal palace had ''multiple courtyards''; the card''s ''many courtyards'' sharpens the quantifier - write ''multiple courtyards''."}]'::jsonb),
    ('4f366f34-983c-42e1-a89d-7e8f5f77cdce'::uuid, 'card_description', 'At 2,430 meters, about 104 caves and rock shelters around Machu Picchu held the remains of about 174 individuals, interpreted largely as yanaconas rather than the Inca elite.', NULL, 'teaser-card-s039:4f366f34-983c-42e1-a89d-7e8f5f77cdce:card_description', 'teaser-card-s039 (card-clear-recheck-check-failed): card cleared (recheck-check-failed)', '||c2398fffdc17f4935396e3f988a8ff2a1080c6cf69340a8dd57859365762daa3', '[{"source": "lane WB run wb-recheck-2026-10-24: recheck-check-failed", "url": "output/remediation/teaser/runs/wb-recheck-2026-10-24/OUTCOMES.jsonl", "quote": "No sentence of the description supports the claim: the caves and rock shelters lie at 2,430 meters; The card places the caves and rock shelters at 2,430 meters, but S1 gives that elevation only for the citadel''s mountain ridge; no sentence gives the elevation of the burial caves."}]'::jsonb),
    ('5144ec8c-3071-4484-83d5-aded69094bb0'::uuid, 'card_description', 'In Luhansk Oblast, Ukraine, the Merheleva Ridge is an Eneolithic temple and burial complex of four large stone kurgans, officially announced on September 7, 2006.', NULL, 'teaser-card-s039:5144ec8c-3071-4484-83d5-aded69094bb0:card_description', 'teaser-card-s039 (card-clear-recheck-adversarial-failed): card cleared (recheck-adversarial-failed)', '||438ce4cc758d9f99d40d87a85586930642ae43e8749cabfefb275053298ddcb9', '[{"source": "lane WB run wb-recheck-2026-10-24: recheck-adversarial-failed", "url": "output/remediation/teaser/runs/wb-recheck-2026-10-24/OUTCOMES.jsonl", "quote": "The card states as fact that Merheleva Ridge is an Eneolithic temple complex, but reputable sources disagree: the excavator Viktor Klochko dated it from about 4000 BC and called it a temple-and-burial complex (Archaeology magazine, https://archive.archaeology.org/0701/trenches/fact.html), while the Ukrainian Wikipedia calls it ''археологічна пам''ятка бронзової доби'' (https://uk.wikipedia.org/wiki/Мергелева_гряда_(археологічна_пам''ятка)) and the Russian Wikipedia records burials of the Catacomb and Srubna cultures (''Погребения донецкой катакомбной и срубной культуры'') and the verdict of Luhansk geologists and archaeologists at a 2007 conference that ''кроме обычных и самых рядовых курганов для Донбасса, на «Мергелевой гряде» других искусственных сооружений нет'', with the 2007 debate in the journal Arkheolohiia (Gershkovych and Sanzharov) finding ''никаких явных доказательств искусственного происхождения «стен», «дорог» и «платформ» на Мергелевой гряде нет'' (https://ru.wikipedia.org/wiki/Мергелевая_гряда); the card must hedge the temple identification and the Eneolithic date as the excavators'' interpretation, or drop them."}]'::jsonb);

DO $$
DECLARE
    bad      INTEGER;
    moved    INTEGER := 0;
    expected INTEGER := 54;
    r        RECORD;
BEGIN
    -- expected is the plan's own row count, rendered here, and not a second count of the
    -- temp table the loop below iterates: counting the same table twice would make the
    -- comparison after the loop a tautology. The instance that makes a short loop
    -- unreachable is apply_remediation_change, which raises unless exactly one row
    -- matched; this guard is what reports a loop that changed fewer rows than the plan.

    -- scope guard 1: every planned row is a card_stats row of a curated site that still exists
    SELECT count(*) INTO bad
      FROM _teaser_card_plan p LEFT JOIN card_stats t ON t.site_id = p.site_id
      LEFT JOIN unified_sites u ON u.id = p.site_id
     WHERE t.site_id IS NULL OR u.id IS NULL OR u.source_id <> 'ancient_nerds';
    IF bad > 0 THEN
        -- the source name is a RAISE argument, never part of the quoted message: a name
        -- spliced into the message text only parses while the name happens to contain no
        -- quote, which is a property of today's value and not of this code. G0's guard is
        -- the shape this one copies.
        RAISE EXCEPTION 'teaser card: % planned row(s) are not % sites', bad, 'ancient_nerds';
    END IF;

    -- scope guard 2: the plan is a set of real changes, each one writable in its column
    -- (compared in the column's own type; CASE, because only CASE fixes the order in
    -- which the casts are evaluated)
    SELECT count(*) INTO bad FROM _teaser_card_plan p
     WHERE p.new_value = '' OR CASE p.column_name
                WHEN 'card_description' THEN p.new_value::character varying IS NOT DISTINCT FROM p.old_value::character varying OR length(p.new_value) > 200
                ELSE true END;
    IF bad > 0 THEN
        RAISE EXCEPTION 'teaser card: % planned row(s) are not writable changes', bad;
    END IF;

    -- scope guard 3: every planned row still holds the old value the plan names
    SELECT count(*) INTO bad
      FROM _teaser_card_plan p JOIN card_stats t ON t.site_id = p.site_id
     WHERE CASE p.column_name
                WHEN 'card_description' THEN t.card_description IS DISTINCT FROM p.old_value::character varying
                ELSE true END;
    IF bad > 0 THEN
        RAISE EXCEPTION 'teaser card: % planned row(s) no longer hold the planned old value', bad;
    END IF;

    -- scope guard 5: every planned row still holds the input its value was derived from
    SELECT count(*) INTO bad
      FROM (SELECT DISTINCT site_id, premise FROM _teaser_card_plan) p JOIN unified_sites u ON u.id = p.site_id
     WHERE (coalesce(u.raw_data -> '_card_provenance' ->> 'text_sha256', '') || '|' || coalesce(u.raw_data -> '_card_provenance' ->> 'desc_sha256', '') || '|' || encode(sha256(convert_to(coalesce(u.description, ''), 'UTF8')), 'hex')) IS DISTINCT FROM p.premise;
    IF bad > 0 THEN
        RAISE EXCEPTION 'teaser card: % planned row(s) no longer hold the premise the plan derived its value from', bad;
    END IF;

    -- the only writer: the conditional UPDATE and its journal row commit together, and
    -- the function raises unless exactly one row matched
    FOR r IN SELECT * FROM _teaser_card_plan ORDER BY site_id, column_name LOOP
        moved := moved + apply_remediation_change(
            'card_stats', r.column_name, 'site_id', r.site_id::text,
            r.old_value, r.new_value,
            'WB/teaser-card', 'wb-teaser-card-s039', r.change_key, 'opus-checked', r.evidence, r.site_id);
    END LOOP;

    IF moved <> expected THEN
        RAISE EXCEPTION 'teaser card: % row(s) changed, % planned', moved, expected;
    END IF;

    -- invariant 1: every planned row now holds the new value
    SELECT count(*) INTO bad
      FROM _teaser_card_plan p JOIN card_stats t ON t.site_id = p.site_id
     WHERE CASE p.column_name
                WHEN 'card_description' THEN t.card_description IS DISTINCT FROM p.new_value::character varying
                ELSE true END;
    IF bad > 0 THEN
        RAISE EXCEPTION 'teaser card: % planned row(s) do not hold the new value', bad;
    END IF;

    -- invariant 2: the journal and the data agree, row for row, in both directions
    SELECT count(*) INTO bad
      FROM _teaser_card_plan p LEFT JOIN remediation_change_log l
        ON l.row_pk = p.site_id::text AND l.table_name = 'card_stats'
       AND l.column_name = p.column_name
       AND l.run_stamp = 'wb-teaser-card-s039'
     WHERE l.id IS NULL
        OR l.new_value IS DISTINCT FROM p.new_value
        OR l.old_value IS DISTINCT FROM p.old_value;
    IF bad > 0 THEN
        RAISE EXCEPTION 'teaser card: % planned row(s) have no matching journal row', bad;
    END IF;

    SELECT count(*) INTO bad FROM remediation_change_log l
     WHERE l.run_stamp = 'wb-teaser-card-s039'
       AND (l.table_name <> 'card_stats' OR l.column_name NOT IN ('card_description'));
    IF bad > 0 THEN
        RAISE EXCEPTION 'teaser card: this run stamp journalled % row(s) outside card_stats.(card_description)', bad;
    END IF;

    RAISE NOTICE 'teaser card: % of % planned cell(s) changed and journalled over 54 curated site(s)',
        moved, expected;
END $$;

ROLLBACK;
-- after ROLLBACK: nothing may have changed
SELECT 'journal rows for this run stamp' AS metric, count(*)::text AS value
  FROM remediation_change_log WHERE run_stamp = 'wb-teaser-card-s039'
UNION ALL
SELECT 'curated sites whose teaser provenance does not hash their live card', count(*)::text
  FROM unified_sites
 WHERE source_id = 'ancient_nerds' AND raw_data ? '_card_provenance' AND NOT EXISTS (SELECT 1 FROM card_stats cs WHERE cs.site_id = unified_sites.id AND encode(sha256(convert_to(cs.card_description, 'UTF8')), 'hex') = unified_sites.raw_data -> '_card_provenance' ->> 'text_sha256')
UNION ALL
SELECT 'curated sites', count(*)::text
  FROM unified_sites WHERE source_id = 'ancient_nerds'
UNION ALL
-- `_teaser_card_plan` is a CREATE TEMP TABLE, so it lives in this session's `pg_temp_N` schema and
-- `nspname = 'public'` could never match it - the old form of this read was 0 whatever happened.
-- `to_regclass('pg_temp....')` resolves the current session's temp schema and is NULL when the
-- table is gone, so this reads 1 exactly when a leftover exists.
SELECT 'temp table _teaser_card_plan left behind',
       (to_regclass('pg_temp._teaser_card_plan') IS NOT NULL)::int::text
